    HStack(spacing: 16) {
        ForEach(AchievementRarity.allCases, id: \.self) { rarity in
            VStack(spacing: 6) {
                BadgeMedallion(symbol: "flame.fill", rarity: rarity, isLocked: false, size: 60)
                Text(rarity.displayName).font(.caption2)
            }
        }
    }
    .padding()
}

